/**
 * @distilled.cloud/openai — OpenAI SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from OpenAI's
 * OpenAPI description) — one module per API area (`responses`, `chat`,
 * `files`, `projects`, …). Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as OpenAI from "@distilled.cloud/openai";
 *
 * const program = Effect.gen(function* () {
 *   const response = yield* OpenAI.responses.createResponse({
 *     model: "gpt-5-nano",
 *     input: "Say hello",
 *   });
 *   return response.output;
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   OpenAI.CredentialsFromEnv,
 *   OpenAI.OpenAIProtocol,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 */
export {
  Credentials,
  CredentialsFromEnv,
  DEFAULT_API_BASE_URL,
  credentials,
  fromApiKey,
} from "./credentials.ts";
export type { Config as OpenAIClientConfig } from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { OpenAIProtocol, type OpenAIOpError, type OpenAIOpContext } from "./protocol.ts";
export { paginateAfter, paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
